graphql.query:
query Me {
  me {
    id
    username
    email
    firstName
    secondName
    description
    profileImage
    creationDate
    modifiedDate
  }
}

query SuggestedUsers {
  suggestedUsers {
    id
    username
    description
    photo
  }
}

query AllGroups {
  allGroups {
    id
    title
    photo
    membersCount
  }
}

query Group($id: Int!) {
  group(id: $id) {
    id
    title
    photo
    membersCount
  }
}

query PostsTotal {
  postsTotal
}

query PostComments($postId: Int!) {
  postComments(postId: $postId) {
    id
    postId
    authorId
    text
    creationDate
    modifiedDate
  }
}

query AllComments {
  allComments {
    id
    postId
    authorId
    text
    creationDate
    modifiedDate
  }
}

query MeComments {
  meComments {
    id
    postId
    authorId
    text
    creationDate
    modifiedDate
  }
}

query MeCommentsCount {
  meCommentsCount
}

query MeLikes {
  meLikes {
    id
    userId
    postId
    creationDate
  }
}

query MeLikesCount {
  meLikesCount
}

mutation Login($email: String!, $password: String!) {
  login(email: $email, password: $password) {
    token
    refreshToken
    expiresIn
    user {
      id
      username
      email
      firstName
      secondName
      description
      profileImage
      creationDate
      modifiedDate
    }
  }
}

mutation Refresh($refreshToken: String!) {
  refresh(refreshToken: $refreshToken) {
    token
    refreshToken
    expiresIn
  }
}

mutation Signup($email: String!, $password: String!) {
  signup(email: $email, password: $password) {
    message
    user {
      id
      username
      email
      firstName
      secondName
      description
      profileImage
      creationDate
      modifiedDate
    }
  }
}

mutation UpdateAccount($input: UpdateAccountInput!) {
  updateAccount(input: $input) {
    message
    user {
      id
      username
      email
      firstName
      secondName
      description
      profileImage
      creationDate
      modifiedDate
    }
    token
    refreshToken
    expiresIn
  }
}

mutation Logout($refreshToken: String) {
  logout(refreshToken: $refreshToken)
}

mutation UpdateProfile($input: UpdateProfileInput!) {
  updateProfile(input: $input) {
    id
    username
    email
    firstName
    secondName
    description
    profileImage
    creationDate
    modifiedDate
  }
}

